298			{Time: 1, MoveVariance: 0, Observations: []Observation{{ID: "L", X: 0, Y: 0}}},
299			{Time: 2, MoveVariance: 0, Observations: []Observation{{ID: "L", X: 0, Y: 0}}},
300		}})
301		if err != nil {
302			t.Fatalf("ImportSegment: %v", err)
303		}
304		if res.EndPose.X != 1e308 || res.EndPose.Variance != 1e308 {
305			t.Fatalf("end pose = %+v, want X=1e308 variance 1e308", res.EndPose)
306		}
307		lms, _ := m.LandmarksInRect(Rect{MinX: 0, MinY: -1, MaxX: math.MaxFloat64, MaxY: 1})
308		if len(lms) != 1 || lms[0].X != 1e308 || lms[0].Y != 0 || lms[0].Count != 2 {
309			t.Fatalf("landmark = %+v, want (1e308,0) count 2", lms)
310		}
311	}
