package posemap

import (
	"path/filepath"
	"testing"
)

func TestReproPureTranslation(t *testing.T) {
	path := filepath.Join(t.TempDir(), "map.bin")
	cfg := Config{
		InitialTime: 0, InitialX: 1e308, InitialY: 0, InitialHeading: 0,
		InitialVariance: 0, MaxInterval: 100, MergeDistance: 10,
	}
	m, err := Create(path, cfg)
	if err != nil {
		t.Fatal(err)
	}
	defer m.Close()
	if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
		{Time: 100},
		{Time: 200, DX: -1e308, Observations: []Observation{{ID: "L"}}},
		{Time: 300, DX: -1e308, Observations: []Observation{{ID: "L"}}},
	}}); err != nil {
		t.Fatal(err)
	}
	for _, tt := range []int64{100, 200, 300} {
		p, _ := m.PoseAt(tt)
		t.Logf("before t=%d -> x=%v y=%v", tt, p.X, p.Y)
	}
	rec, err := m.Correct(Correction{ID: "c", Anchor: 100, Target: CorrectionTarget{X: 1e308, Y: 1}})
	if err != nil {
		t.Fatalf("Correct: %v", err)
	}
	for _, pc := range rec.Poses {
		t.Logf("rec t=%d before=(%v,%v) after=(%v,%v)", pc.Before.Time, pc.Before.X, pc.Before.Y, pc.After.X, pc.After.Y)
	}
	for _, lc := range rec.Landmarks {
		t.Logf("lm %s before=(%v,%v) after=(%v,%v) count=%d", lc.ID, lc.Before.X, lc.Before.Y, lc.After.X, lc.After.Y, lc.After.Count)
	}
	if err := m.Close(); err != nil {
		t.Fatal(err)
	}
	m2, err := Open(path)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	defer m2.Close()
	for _, tt := range []int64{100, 200, 300} {
		p, _ := m2.PoseAt(tt)
		t.Logf("reopen t=%d -> x=%v y=%v", tt, p.X, p.Y)
	}
}

