196		}
197	}
198	
199	// 恒等校正只放宽“几何相同但相对偏移计算溢出”这一种误拒绝；其余拒绝规则不变：
200	// 负方差、非有限目标、有限目标但累计后非有限（标明锚点时间）、真正改变位置
201	// 或朝向的校正保留原有 non_finite 行为。任何拒绝不留部分更新。
202	func TestCorrectionVarianceOnlyRejections(t *testing.T) {
203		build := func(t *testing.T, merge float64) *Map {
204			m := newMap(t, Config{
205				InitialTime: 0, InitialX: -1e308, InitialY: 0, InitialHeading: 0,
206				InitialVariance: 1, MaxInterval: 100, MergeDistance: merge,
207			})
